CREATE TABLE "btw_clients" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "btw_clients_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" uuid DEFAULT app.uid() NOT NULL,
	"name" text NOT NULL,
	"payment_lag" integer DEFAULT 0 NOT NULL,
	"vat_percent" integer DEFAULT 21 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "btw_clients_user_id_id_unique" UNIQUE("user_id","id"),
	CONSTRAINT "btw_clients_name_check" CHECK (char_length("btw_clients"."name") between 1 and 60),
	CONSTRAINT "btw_clients_payment_lag_check" CHECK ("btw_clients"."payment_lag" between 0 and 2),
	CONSTRAINT "btw_clients_vat_percent_check" CHECK ("btw_clients"."vat_percent" in (0, 21))
);
