-- The list of BTW clients (several clients, each with its own payment lag and rate). Hand-written additions to what
-- drizzle-kit made.

-- Same access as every other table: only the app role, only a user's own rows.
GRANT SELECT, INSERT, UPDATE, DELETE ON "btw_clients" TO kasboek_app;
--> statement-breakpoint
GRANT USAGE, SELECT ON SEQUENCE "btw_clients_id_seq" TO kasboek_app;
--> statement-breakpoint
CREATE POLICY tenant ON "btw_clients" FOR ALL TO kasboek_app USING (user_id = (SELECT app.uid())) WITH CHECK (user_id = (SELECT app.uid()));
--> statement-breakpoint

-- Supabase hands new tables to its API roles by default; take it away again (see 0002).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')
     AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON "btw_clients" FROM anon, authenticated;
    REVOKE ALL ON SEQUENCE "btw_clients_id_seq" FROM anon, authenticated;
  END IF;
END
$$;
--> statement-breakpoint

-- Move the single client into the list, exactly as the app read it until now (getBtwSettings): every user gets one
-- client, named user_settings.btw_client or the default "Featurn" when that is null or there is no settings row at all,
-- with user_settings.btw_payment_lag (0 without a settings row) and the standard 21%. So nobody's numbers change.
-- The old columns user_settings.btw_client and btw_payment_lag stay in place (old backups and a rollback can still read
-- them) but the app no longer reads them. Keep 'Featurn' in step with DEFAULT_BTW_INCOME_MATCH in src/lib/btw/defaults.ts.
INSERT INTO "btw_clients" ("user_id", "name", "payment_lag", "vat_percent")
SELECT u.user_id, coalesce(s.btw_client, 'Featurn'), coalesce(s.btw_payment_lag, 0), 21
FROM "app_users" u
LEFT JOIN "user_settings" s ON s.user_id = u.user_id
WHERE NOT EXISTS (SELECT 1 FROM "btw_clients" c WHERE c.user_id = u.user_id);
